def get_children_of_parent(parent_node, child_node):
    """
    Returns the children of the parent node, or None if the parent node is not found.
    """
    if parent_node is None:
        return None
    if child_node is None:
        return None
    if parent_node.children is None:
        return None
    if child_node.children is None:
        return None
    return get_children_of_parent(parent_node.children, child_node)
