from typing import Any, Dict

def convert_to_b2o(coins: Dict[str, Any]) -> Dict[str, Any]:
    """
    Converts a list of coins to a dictionary of b2o values.
    """
    b2o_values = {}
    for coin in coins:
        if coin in b2o_values:
            b2o_values[coin] += 1
        else:
            b2o_values[coin] = 1
    return b2o_values
